import * as THREE from './assets/three.module.js';
export function createDrivingFeedback(world){
 let context=null,engine=null,sub=null,engineGain=null,subGain=null,filter=null,hiss=null,hissGain=null,shake=0,smokeTimer=0,gear=1;
 const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const c=canvas.getContext('2d'),g=c.createRadialGradient(32,32,3,32,32,30);g.addColorStop(0,'#ffffffaa');g.addColorStop(.4,'#ffffff60');g.addColorStop(1,'#ffffff00');c.fillStyle=g;c.fillRect(0,0,64,64);const tex=new THREE.CanvasTexture(canvas);
 const smoke=Array.from({length:44},()=>{const material=new THREE.SpriteMaterial({map:tex,color:'#e0decd',transparent:true,depthWrite:false,opacity:0});const mesh=new THREE.Sprite(material);mesh.visible=false;world.add(mesh);return {mesh,life:0,max:1,vx:0,vz:0};});let cursor=0;
 function init(audio){if(context)return;context=audio;engine=audio.createOscillator();sub=audio.createOscillator();engine.type='sawtooth';sub.type='triangle';engineGain=audio.createGain();subGain=audio.createGain();filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=250;engineGain.gain.value=subGain.gain.value=0;engine.connect(filter);filter.connect(engineGain);sub.connect(subGain);engineGain.connect(audio.destination);subGain.connect(audio.destination);engine.start();sub.start();
  const buffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),data=buffer.getChannelData(0);let smooth=0;for(let i=0;i<data.length;i++){smooth=.88*smooth+.12*(Math.random()*2-1);data[i]=smooth;}hiss=audio.createBufferSource();hiss.buffer=buffer;hiss.loop=true;const band=audio.createBiquadFilter();band.type='bandpass';band.frequency.value=1600;hissGain=audio.createGain();hissGain.gain.value=0;hiss.connect(band);band.connect(hissGain);hissGain.connect(audio.destination);hiss.start();
 }
 function hit(force,muted=false){shake=Math.min(.42,shake+Math.min(25,force)*.017);if(!context||muted)return;const o=context.createOscillator(),a=context.createGain(),now=context.currentTime;o.type='triangle';o.frequency.setValueAtTime(105,now);o.frequency.exponentialRampToValueAtTime(29,now+.23);a.gain.setValueAtTime(Math.min(.17,.035+force*.004),now);a.gain.exponentialRampToValueAtTime(.001,now+.25);o.connect(a);a.connect(context.destination);o.start();o.stop(now+.26);o.onended=()=>{o.disconnect();a.disconnect();};}
 function update(dt,car,input,{active,muted,paused,reducedMotion=false}){const speed=Math.abs(car?.speed||0),skid=active&&!paused&&car.y<.25&&speed>5&&(car.drifting||(car.braking&&speed>10));
  if(context){const t=context.currentTime,nextGear=Math.min(5,1+Math.floor(speed/7)),rpm=55+(speed%7)*13+(input.throttle>0?15:0),volume=active&&!paused&&!muted?1:0;gear=nextGear;engine.frequency.setTargetAtTime(rpm,t,.08);sub.frequency.setTargetAtTime(rpm*.5,t,.09);filter.frequency.setTargetAtTime(240+speed*20+(input.throttle>0?160:0),t,.14);engineGain.gain.setTargetAtTime(volume*(.011+Math.min(speed,30)*.0004),t,.08);subGain.gain.setTargetAtTime(volume*.026,t,.1);hissGain.gain.setTargetAtTime(volume*(skid?.55:car.boosting?.055:0),t,.1);}
  if(!paused){smokeTimer-=dt;shake*=Math.exp(-dt*9);if(skid&&smokeTimer<=0){smokeTimer=.055;for(const side of [-1,1]){const p=smoke[cursor++%smoke.length];p.life=p.max=1.15;p.mesh.visible=true;p.mesh.position.set(car.x+Math.cos(car.heading)*side*.87-Math.sin(car.heading)*1.5,.26,car.z-Math.sin(car.heading)*side*.87-Math.cos(car.heading)*1.5);p.mesh.scale.setScalar(.48);p.vx=-car.vx*.1+side*.5;p.vz=-car.vz*.1;}}
   for(const p of smoke){if(p.life<=0)continue;p.life-=dt;p.mesh.visible=p.life>0;if(p.life>0){p.mesh.position.x+=p.vx*dt;p.mesh.position.z+=p.vz*dt;p.mesh.position.y+=dt*.6;p.mesh.scale.setScalar(.45+(1-p.life/p.max)*1.55);p.mesh.material.opacity=p.life/p.max*.42;}}
  }if(reducedMotion)shake=0;
 }
 function cameraKick(camera,time){if(shake>.002){camera.position.x+=Math.sin(time*83)*shake;camera.position.y+=Math.cos(time*67)*shake*.7;}}
 function clear(){for(const p of smoke){p.life=0;p.mesh.visible=false;}shake=0;}
 return{init,hit,update,cameraKick,clear,get gear(){return gear;}};
}
